"""Public R API observations generated by oracle/collinear_fixtures.R."""
import json
from pathlib import Path

import numpy as np
import pytest

from ecotrajpy import define_trajectories, trajectory_angles, trajectory_directionality
from ecotrajpy import fast
from ecotrajpy.nulls import directionality_coords

CASES = json.loads((Path(__file__).parent / 'fixtures/collinear_cases.json').read_text())['cases']


@pytest.mark.parametrize('case', CASES, ids=lambda c: c['id'])
@pytest.mark.parametrize('add', [True, False])
def test_collinear_r_oracle(case, add):
    C = np.asarray(case['C'], dtype=float)
    x = define_trajectories(case['d'], ['path'] * len(C))
    suffix = '' if add else '_noadd'
    expected = np.asarray(case['angles' + suffix], dtype=float)
    np.testing.assert_allclose(trajectory_angles(x, all=True, stats=False, add=add),
                               expected, rtol=1e-8, atol=1e-10)
    expected_d = np.asarray(case['directionality' + suffix], dtype=float)
    np.testing.assert_allclose(trajectory_directionality(x, add=add).iloc[0],
                               expected_d, rtol=1e-8, atol=1e-10)


@pytest.mark.parametrize('case', CASES, ids=lambda c: c['id'])
def test_collinear_fast_backends(case):
    C = np.asarray(case['C'], dtype=float)
    reference = directionality_coords(C)
    expected = np.asarray(case['directionality'], dtype=float)
    for actual in (reference, fast.directionality_coords_fast(C), fast._directionality_numpy(C)):
        np.testing.assert_allclose(actual, expected, rtol=1e-8, atol=1e-10)
        np.testing.assert_allclose(actual, reference, rtol=0, atol=1e-12)


def test_raw_kernel_callable_from_numba():
    numba = pytest.importorskip('numba')
    # ext2 imports this raw dispatcher and calls it inside its own jitted kernel.
    @numba.njit(cache=False)
    def caller(C):
        return fast._directionality_impl(C)
    C = np.asarray(CASES[0]['C'], dtype=float)
    np.testing.assert_allclose(caller(C), CASES[0]['directionality'], rtol=0, atol=1e-12)
